		}
		output.Write(encoded)
		output.WriteByte('\n')
	}
	return protocol.CompactTranscriptResponse{
		Transcript: base64.StdEncoding.EncodeToString(output.Bytes()),
	}, nil
}

func readSDKMessages(path string) ([]sdkMessage, error) {
